// ===== تنظیمات: فقط این بخش را ویرایش کنید =====
const DJANGO_URL = 'http://host.docker.internal:8000';   // روی سرور: http://web:8000
const DRY_RUN = false;       // true = فقط گزارش، بدون ذخیره؛ false = ذخیره در دیتابیس
const CHUNK = 400;           // حداکثر ردیف در هر درخواست (سقف Django: 500)
const MAX_PAGES = 600;       // سقف ایمنی صفحه‌ها برای هر نوع مرکز

// منبع «دانا»: API عمومی خود صفحه مراکز درمانی بیمه دانا
// (https://appsef.dana-insurance.ir/subportal) با ۲۵ ردیف در هر صفحه.
const SOURCES = [
  {
    name: 'dana',
    insurance: 'بیمه دانا',
    api: 'https://appsef.dana-insurance.ir/SubPortal/HealthCenter/GetAllMedicalCenters',
    kinds: [                 // نوع مرکز دانا -> دسته‌بندی نوبت‌یار
      { id: 1219, category: 'DOCTOR' },    // مطب
      { id: 1221, category: 'DENTIST' },   // دندان‌پزشکی
      { id: 1212, category: 'DOCTOR' },    // کلینیک / درمانگاه
    ],
  },
];
// ================================================

// یکدست‌سازی حروف (بدون همزه، طبق قاعده پروژه) و حذف علامت‌های جهت
const fix = (v) => (v === undefined || v === null ? '' : String(v))
  .replace(/\u200f|\u200e|\u202b|\u202c/g, '')
  .replace(/ي/g, 'ی').replace(/ك/g, 'ک').replace(/ۀ/g, 'ه')
  .replace(/[\u0623\u0625\u0622]/g, (c) => (c === '\u0622' ? 'آ' : 'ا'))
  .replace(/\u0624/g, 'و').replace(/\u0626/g, 'ی').replace(/[\u0621\u0654]/g, '')
  .replace(/^["'\s]+|["'\s]+$/g, '').replace(/\s+/g, ' ').trim();

const URL = DJANGO_URL + '/api/internal/directory-sync/';
const out = [];
const errors = [];
for (const src of SOURCES) {
  const mapped = [];
  for (const kind of src.kinds) {
    let page = 1, pages = 1;
    try {
      while (page <= pages && page <= MAX_PAGES) {
        const res = await this.helpers.httpRequest({
          method: 'GET', url: src.api, json: true, timeout: 30000,
          qs: { centerKindId: kind.id, Name: '', province: '', city: '', address: '', NoeTakhasos: '', pageNo: page },
        });
        pages = Math.ceil((res.count || 0) / (res.pageSize || 25));
        for (const r of (res.data || [])) {
          const title = fix(r.Name);
          if (!title) continue;
          mapped.push({
            title, city: fix(r.City), province: fix(r.Province), phone: fix(r.Tel),
            address: fix(r.Address), category: kind.category, insurances: src.insurance,
            latitude: r.Latitude == null ? '' : r.Latitude, longitude: r.Longitude == null ? '' : r.Longitude,
          });
        }
        page += 1;
      }
    } catch (e) {
      errors.push(src.name + ' kind ' + kind.id + ' page ' + page + ': ' + e.message);
    }
  }
  for (let i = 0; i < mapped.length; i += CHUNK) {
    out.push({ json: { url: URL, source: 'n8n-' + src.name, dry_run: DRY_RUN, rows: mapped.slice(i, i + CHUNK) } });
  }
  if (!mapped.length) errors.push(src.name + ': no rows');
}
if (errors.length) out.push({ json: { url: URL, source: 'n8n-errors', dry_run: DRY_RUN, rows: [], error: errors.join(' | ').slice(0, 800) } });
return out;

// خلاصه اجرا؛ اگر منبعی خطا داد یا Django خطا برگرداند، اجرا قرمز می‌شود.
const items = $input.all().map((i) => i.json);
const fetchErrors = $('Fetch and normalize').all().map((i) => i.json).filter((j) => j.error).map((j) => j.source + ': ' + j.error);
const bad = items.filter((j) => typeof j.total !== 'number').map((j) => 'Django: ' + JSON.stringify(j).slice(0, 200));
const problems = [...fetchErrors, ...bad];
const sum = (k) => items.reduce((a, j) => a + (Number(j[k]) || 0), 0);
const summary = { dry_run: items.some((j) => j.dry_run === true), total: sum('total'), created: sum('created'),
  duplicates: sum('duplicates'), invalid: sum('invalid'), linked: sum('linked'), problems: problems.length };
if (problems.length) throw new Error('sync problems: ' + problems.join(' | ').slice(0, 500));
return [{ json: summary }];
